import { addTranslationListener, translate } from '@ps-refarch-ux/mfe-utils';
import { createElement, createElementIf, dynamicAttr, dynamicText, updateConditionalElements, updateDynamicAttribute, updateDynamicProperty, updateDynamicText } from '../shared/dom-manipulation';
import { NeonWidget } from '../shared/neon-widget';
import { showPopper } from '../shared/poppers';
import './neon-button-split.scss';
export class NeonButtonSplit extends NeonWidget {
    constructor() {
        super(...arguments);
        this.widgetTag = 'neon-button-split';
    }
    //Any attribute that should be watched for changes should be listed here.
    static get observedAttributes() {
        return [
            'id',
            'data-text',
            'data-menu-heading',
            'data-aria-label',
            'disabled',
            'data-tooltip-text',
            'data-tooltip-placement',
            'data-popper-placement',
            'data-options-tooltip-text'
        ];
    }
    static get inputProperties() {
        return [
            'options',
            'context'
        ];
    }
    set options(selectOption) {
        if (selectOption === this.splitButtonOptions) {
            return;
        }
        this.splitButtonOptions = selectOption;
        this.itemPicker = this.renderPopperMenuElement();
        updateDynamicProperty(this, 'menuOptions');
        this.redraw();
    }
    get options() {
        return this.splitButtonOptions;
    }
    //when the attributes change this will run
    attributeChanged(attrName, oldVal, newVal) {
        super.attributeChanged(attrName, oldVal, newVal);
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        switch (attrName) {
            case 'id':
                updateDynamicAttribute(this, 'id');
                break;
            case 'data-text':
                updateDynamicText(this);
                break;
            case 'data-aria-label':
                updateDynamicAttribute(this, 'aria-label');
                break;
            case 'data-menu-heading':
                updateDynamicText(this);
                break;
            case 'disabled':
                updateDynamicAttribute(this, 'disabled');
                updateDynamicProperty(this, 'options');
                updateConditionalElements(this);
                break;
            case 'data-tooltip-text':
            case 'data-options-tooltip-text':
                updateConditionalElements(this);
                updateDynamicText(this);
                break;
            case 'data-tooltip-placement':
                updateDynamicAttribute(this, 'data-placement');
                updateDynamicAttribute(this, 'data-item-tooltip-placement');
                break;
            case 'data-popper-placement':
                updateDynamicAttribute(this, 'data-popper-placement');
                break;
            default:
        }
    }
    render() {
        return [
            createElement('button', {
                attrs: {
                    class: 'neon-split-button-primary-action' + this.getSplitButtonClasses(),
                    'aria-label': dynamicAttr(() => {
                        return this.getAttribute('data-aria-label') !== null ? this.getAttribute('data-aria-label') : this.getAttribute('data-text');
                    }),
                    id: dynamicAttr(() => { return this.getAttribute('id') + '-button'; }),
                    disabled: dynamicAttr(() => { return this.getAttribute('disabled') === 'true' ? 'true' : undefined; }),
                },
                // No click listener here. We just let the click even bubble up to whoever is listening
                // listeners: {
                //   click: () => { }
                // },
                text: dynamicText(() => { return this.getAttribute('data-text'); }),
            }),
            createElementIf(() => {
                return this.splitButtonOptions !== undefined && this.itemPicker !== undefined;
            }, 'button', {
                attrs: {
                    id: dynamicAttr(() => { return this.getAttribute('id') + '-menu'; }),
                    class: 'neon-split-button-secondary-action',
                    'aria-label': dynamicAttr(() => {
                        return this.getAttribute('data-aria-label') !== null ? this.getAttribute('data-aria-label') : this.getAttribute('data-menu-heading');
                    }),
                    disabled: dynamicAttr(() => {
                        return this.getAttribute('disabled') === 'true' ? 'true' : undefined;
                    })
                },
                listeners: {
                    click: (event) => {
                        if (this.removePopper != null) {
                            event.stopPropagation();
                            event.preventDefault();
                            this.removePopper();
                            return;
                        }
                        // const relativeElement = this.querySelector('#' + this.getAttribute('id') + '-menu') as HTMLElement;
                        const relativeElement = this;
                        const placement = (this.getAttribute('data-popper-placement') || 'bottom-start');
                        this.removePopper = showPopper(relativeElement, this.itemPicker, {
                            placement: placement,
                            offset: 4,
                            trapFocus: true,
                            makePopperSameWidthAs: 'relative-element',
                            popperPostClosedCallback: () => {
                                delete this.removePopper;
                                this.itemPicker.filterString = '';
                            },
                            popperShownCallback: () => {
                                if (this.itemPicker != null) {
                                    this.itemPicker.setFocus();
                                }
                            },
                            clickTarget: relativeElement,
                        });
                        event.stopPropagation();
                    }
                },
            }, () => {
                return createElement('neon-2_20_1-icon', {
                    attrs: {
                        class: 'neon-split-button-menu-icon',
                        'data-icon': 'caret-down',
                        'data-size': 'small',
                    }
                });
            }),
            this.renderToolTip(),
            this.renderOptionsToolTip(),
        ];
    }
    connectedCallback() {
        super.connectedCallback();
        this.i18nUnsubscribe = addTranslationListener(() => {
            updateDynamicText(this);
        });
    }
    disconnectedCallback() {
        if (this.i18nUnsubscribe != null) {
            this.i18nUnsubscribe();
            this.i18nUnsubscribe = undefined;
        }
    }
    renderPopperMenuElement() {
        return createElement('neon-2_20_1-item-picker', {
            attrs: {
                id: this.getAttribute('id') + '-popper',
                'data-item-tooltip-placement': dynamicAttr(() => { return this.getAttribute('data-tooltip-placement'); }),
                'data-show-header-text': 'false',
                'data-header-text': dynamicAttr(() => {
                    return this.getAttribute('data-menu-heading') != null ?
                        this.getAttribute('data-menu-heading') :
                        translate('neon|button-split|Select an option');
                }),
                'data-use-arrow': 'false',
                'data-show-filter': dynamicAttr(() => { return this.getAttribute('data-show-filter'); }),
                'data-control-type': 'popper',
                'data-constrain-width': 'false',
                'data-neon-prevent-ancestors-closing': ''
            },
            properties: {
                menuOptions: this.options !== undefined ? this.options : null,
                context: this.context
            },
        });
    }
    renderToolTip() {
        return createElementIf(() => { return this.getAttribute('data-tooltip-text') != null; }, 'neon-2_20_1-tooltip', {
            attrs: {
                'data-target-id': dynamicAttr(() => { return this.getAttribute('id') + '-button'; }),
                'data-placement': dynamicAttr(() => { return this.getAttribute('data-tooltip-placement'); })
            },
            properties: {
                refreshElementBeforeShowing: (element) => {
                    updateDynamicText(element);
                }
            }
        }, () => {
            return createElement('span', {
                text: dynamicText(() => { return this.getAttribute('data-tooltip-text'); })
            });
        });
    }
    renderOptionsToolTip() {
        return createElementIf(() => { return this.getAttribute('data-options-tooltip-text') != null; }, 'neon-2_20_1-tooltip', {
            attrs: {
                'data-target-id': dynamicAttr(() => { return this.getAttribute('id') + '-menu'; }),
                'data-placement': dynamicAttr(() => { return this.getAttribute('data-tooltip-placement'); })
            },
            properties: {
                refreshElementBeforeShowing: (element) => {
                    updateDynamicText(element);
                }
            }
        }, () => {
            return createElement('span', {
                text: dynamicText(() => { return this.getAttribute('data-options-tooltip-text'); })
            });
        });
    }
    getSplitButtonClasses() {
        let splitButtonClass = '';
        if (this.splitButtonOptions === undefined) {
            splitButtonClass += ' neon-split-button-primary-action-only';
        }
        return splitButtonClass;
    }
}
